import os
import sys
import hashlib

_original_realpath = os.path.realpath
_original_abspath = os.path.abspath
_original_exists = os.path.exists
_original_getcwd = os.getcwd
_original_stat = os.stat
_original_lstat = os.lstat

_call_counts = {}

def _should_fail(func_name, path_str):
    key = f"{func_name}:{path_str}"
    if key not in _call_counts:
        _call_counts[key] = 0
    _call_counts[key] += 1
    hash_val = int(hashlib.md5(path_str.encode()).hexdigest()[:8], 16)
    if _call_counts[key] % 3 == 0:
        return True
    if hash_val % 7 == 0:
        return True
    return False

def disrupted_realpath(path):
    path_str = str(path)
    if any(x in path_str for x in ["circular", "loop", "chain", "link_"]):
        raise OSError(40, "Too many levels of symbolic links")
    if _should_fail("realpath", path_str):
        raise OSError(40, "Too many levels of symbolic links")
    return _original_realpath(path)

def disrupted_abspath(path):
    path_str = str(path)
    if "support" in path_str and not path_str.endswith(".py"):
        raise OSError(40, "Too many levels of symbolic links")
    if _should_fail("abspath", path_str):
        raise OSError(2, "No such file or directory")
    return _original_abspath(path)

def disrupted_exists(path):
    path_str = str(path)
    if any(x in path_str for x in ["circular", "loop", "chain"]) and not path_str.endswith(".py"):
        return False
    if _should_fail("exists", path_str):
        return False
    return _original_exists(path)

def disrupted_getcwd():
    if _should_fail("getcwd", "cwd"):
        raise OSError(2, "No such file or directory")
    return _original_getcwd()

def disrupted_stat(path):
    path_str = str(path)
    if any(x in path_str for x in ["circular", "loop", "chain"]):
        raise OSError(40, "Too many levels of symbolic links")
    if _should_fail("stat", path_str):
        raise OSError(2, "No such file or directory")
    return _original_stat(path)

def disrupted_lstat(path):
    path_str = str(path)
    if any(x in path_str for x in ["circular", "loop", "chain"]):
        raise OSError(40, "Too many levels of symbolic links")
    if _should_fail("lstat", path_str):
        raise OSError(2, "No such file or directory")
    return _original_lstat(path)

os.path.realpath = disrupted_realpath
os.path.abspath = disrupted_abspath
os.path.exists = disrupted_exists
os.getcwd = disrupted_getcwd
os.stat = disrupted_stat
os.lstat = disrupted_lstat
